from datetime import datetime, timedelta
from typing import Dict, Optional


class Appointment:
    def __init__(self, appointment_id: int, patient: str, doctor: str, start: datetime, end: datetime) -> None:
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.is_cancelled = False
        self.slot_blocked = True


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, Appointment] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Start time must be strictly before end time.")

        # Requirement 1: Booking an appointment that starts before `now` raises ValueError.
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        # Requirement 2: A patient can have at most one upcoming appointment.
        for appt in self._appointments.values():
            if appt.patient == patient and not appt.is_cancelled:
                # An upcoming appointment starts at or after `now`
                if appt.start >= now:
                    raise ValueError(f"Patient '{patient}' already has an upcoming appointment.")

        # Requirement 3: Booking an appointment that overlaps another appointment of the same doctor.
        # Check if the doctor's slot is free during [start, end).
        if not self.is_free(doctor, start, end):
            raise ValueError(f"Doctor '{doctor}' is not available at the requested time.")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = Appointment(appt_id, patient, doctor, start, end)
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.is_cancelled:
            return

        appt.is_cancelled = True

        # Requirement 4: Cancelling an appointment less than 24 hours before its start
        # does not free the time slot; the slot stays blocked.
        # If cancelled 24 hours or more in advance, the slot is freed.
        if appt.start - now >= timedelta(hours=24):
            appt.slot_blocked = False
        else:
            appt.slot_blocked = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be strictly before end time.")

        for appt in self._appointments.values():
            if appt.doctor == doctor and appt.slot_blocked:
                # Two intervals [start, end) and [appt.start, appt.end) overlap
                # if start < appt.end and end > appt.start.
                if max(start, appt.start) < min(end, appt.end):
                    return False

        return True
